@using RecipeShare.Services
@inject RecipeService Recipes

<div>
    <div class="d-flex align-items-center gap-2">
        <span style="font-size: 1.5rem; cursor: pointer;">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <span @onclick="() => SubmitRating(star)"
                      @onmouseover="() => hoverStar = star"
                      @onmouseout="() => hoverStar = 0"
                      style="color: @(GetStarColor(star))">
                    @(ShouldFill(star) ? "★" : "☆")
                </span>
            }
        </span>
    </div>
    @if (submitted)
    {
        <p class="text-success mt-2 mb-0"><strong>Thanks for rating!</strong> Average: @currentAverage.ToString("F1") (@totalRatings ratings)</p>
    }
    else
    {
        <p class="text-muted mt-2 mb-0">Average: @currentAverage.ToString("F1") (@totalRatings ratings)</p>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    private int hoverStar;
    private bool submitted;
    private double currentAverage;
    private int totalRatings;

    protected override void OnParametersSet()
    {
        currentAverage = CurrentAverage;
        totalRatings = TotalRatings;
    }

    private bool ShouldFill(int star)
    {
        if (hoverStar > 0) return star <= hoverStar;
        return star <= (int)Math.Round(currentAverage);
    }

    private string GetStarColor(int star)
    {
        if (hoverStar > 0 && star <= hoverStar) return "#ffc107";
        if (star <= (int)Math.Round(currentAverage)) return "#ffc107";
        return "#ccc";
    }

    private void SubmitRating(int stars)
    {
        if (submitted) return;
        Recipes.AddRating(RecipeId, stars);
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            currentAverage = recipe.AverageRating;
            totalRatings = recipe.TotalRatings;
        }
        submitted = true;
    }
}

