﻿@page "/"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍳 RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in Recipes.GetCategories())
    {
        <div class="col-md-4 col-sm-6 mb-3">
            <div class="card h-100">
                <div class="card-body d-flex flex-column">
                    <h5 class="card-title">@CategoryIcon(category) @category</h5>
                    <p class="card-text text-muted">
                        @Recipes.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="@($"category/{category}")" class="btn btn-primary mt-auto">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        "Community" => "👥",
        _ => "🍽️"
    };
}

