@page "/category/{CategoryName}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info mt-3">No recipes found in this category.</div>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body d-flex flex-column">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="text-warning mb-2">
                            @for (int i = 1; i <= 5; i++)
                            {
                                <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                            }
                            <span class="text-muted ms-1">(@recipe.TotalRatings ratings)</span>
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary mt-auto">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link mt-3">← Back to categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-link">← Back to home</a>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>Ingredients</h3>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-7">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-4" style="max-width: 400px;">
        <div class="card-body">
            <h5 class="card-title">Rate this recipe</h5>
            <StarRating RecipeId="recipe.Id" CurrentAverage="recipe.AverageRating" TotalRatings="recipe.TotalRatings" />
        </div>
    </div>

    <a href="@($"category/{recipe.Category}")" class="btn btn-link mt-3">← Back to @recipe.Category recipes</a>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(RecipeId);
    }
}

